/**
 * NativeAPI - Tauri Native API 集成
 * 基于 thunderbolt Tauri 架构
 * 提供桌面原生能力增强
 */

// 检测是否在 Tauri 环境
export const isTauri = typeof window !== 'undefined' && window.__TAURI__;
let tauriApi = null;
if (isTauri) {
  tauriApi = window.__TAURI__;
}

/**
 * 显示系统通知
 */
export async function showNotification(title, body) {
  if (!isTauri) {
    // Fallback to web notification API
    if ('Notification' in window && Notification.permission === 'granted') {
      new Notification(title, { body });
      return { success: true, method: 'web-notification' };
    }
    return { success: false, error: '通知权限未授权' };
  }
  
  try {
    const { Notification } = tauriApi.notification;
    await Notification.sendNotification({ title, body });
    return { success: true, method: 'tauri' };
  } catch (e) {
    return { success: false, error: e.message };
  }
}

/**
 * 读取剪贴板
 */
export async function readClipboard() {
  if (!isTauri) {
    try {
      const text = await navigator.clipboard.readText();
      return { success: true, text, method: 'web' };
    } catch (e) {
      return { success: false, error: e.message };
    }
  }
  
  try {
    const { clipboard } = tauriApi;
    const text = await clipboard.readText();
    return { success: true, text, method: 'tauri' };
  } catch (e) {
    return { success: false, error: e.message };
  }
}

/**
 * 写入剪贴板
 */
export async function writeClipboard(text) {
  if (!isTauri) {
    try {
      await navigator.clipboard.writeText(text);
      return { success: true, method: 'web' };
    } catch (e) {
      return { success: false, error: e.message };
    }
  }
  
  try {
    const { clipboard } = tauriApi;
    await clipboard.writeText(text);
    return { success: true, method: 'tauri' };
  } catch (e) {
    return { success: false, error: e.message };
  }
}

/**
 * 打开外部链接
 */
export async function openUrl(url) {
  if (!isTauri) {
    window.open(url, '_blank');
    return { success: true, method: 'web' };
  }
  
  try {
    const { shell } = tauriApi;
    await shell.open(url);
    return { success: true, method: 'tauri' };
  } catch (e) {
    return { success: false, error: e.message };
  }
}

/**
 * 打开文件对话框
 */
export async function openFileDialog(options = {}) {
  if (!isTauri) {
    return { success: false, error: '仅支持桌面端' };
  }
  
  try {
    const { dialog } = tauriApi;
    const result = await dialog.open({
      multiple: options.multiple || false,
      filters: options.filters || []
    });
    return { success: true, path: result, method: 'tauri' };
  } catch (e) {
    return { success: false, error: e.message };
  }
}

